  const dt_ = ORP[type], m = dt_ ? new THREE.Sprite(new THREE.SpriteMaterial({ map: dt_, transparent: true, depthWrite: false, rotation: rand(0, TAU) })) : new THREE.Mesh(tmpl[(Math.random() * tmpl.length) | 0], astMat[type]);
