    const ov = k === 'KeyM' || k === 'Digit2' ? 'map' : k === 'Digit1' ? 'bars' : k === 'Digit3' ? 'hull' : null;
    if (ov){ overlay = overlay === ov ? null : ov; overlayT0 = time; }
