    let g = c.createRadialGradient(sp.x, sp.y, 0, sp.x, sp.y, 340 * inten + 80);
    g.addColorStop(0, `rgba(255,236,200,${0.55 * inten})`); g.addColorStop(0.3, `rgba(255,190,110,${0.2 * inten})`); g.addColorStop(1, 'rgba(255,170,80,0)');
