    const pts = []; for (let i = 0; i <= 16; i++){ const t = i / 16; pts.push(new THREE.Vector2(Math.max(0.002, (1 - t) * 0.0 + Math.pow(1 - t, 0.75) * (0.55 + 0.45 * Math.min(1, t * 7))), t)); }
