    const th=w.th||0.012; const g=new THREE.ExtrudeGeometry(sh,{depth:th,bevelEnabled:true,bevelThickness:th*0.3,bevelSize:th*0.3,bevelSegments:2}); g.translate(0,0,-th/2); g.rotateX(Math.PI/2);
