    c.beginPath(); for (let q = 0; q < 6; q++){ const an = q * Math.PI / 3, X = cx + Math.cos(an) * s * 0.93, Y = cy + Math.sin(an) * s * 0.93; q ? c.lineTo(X, Y) : c.moveTo(X, Y); } c.closePath(); c.stroke();
